define(["jquery"],function($){function initCopyPolicy(context,cfg){let message=$("#proctoringpolicy_copy-message");let limit=cfg&&cfg.limit?parseInt(cfg.limit,10):0;if(isNaN(limit)){limit=0}let warningsCount=0;function showWarning(){if(!message.length||!$.trim(message.html())){return}if(limit>0&&warningsCount>=limit){return}warningsCount++;message.show()}function isBlockedKeyEvent(e){let key=e.key?e.key.toLowerCase():"";let ctrlOrCmd=e.ctrlKey||e.metaKey;if(!ctrlOrCmd){return false}if(key==="c"||key==="v"||key==="x"||key==="a"||key==="p"){return true}return false}function handleKeydown(e){if(isBlockedKeyEvent(e)){e.preventDefault();e.stopPropagation();showWarning()}}function handleClipboardEvent(e){e.preventDefault();e.stopPropagation();showWarning()}function handleContextmenu(e){e.preventDefault();e.stopPropagation();showWarning()}$(document).on("keydown.local_kopere_proctoring_copy",handleKeydown);$(document).on("copy.local_kopere_proctoring_copy",handleClipboardEvent);$(document).on("cut.local_kopere_proctoring_copy",handleClipboardEvent);$(document).on("paste.local_kopere_proctoring_copy",handleClipboardEvent);$(document).on("contextmenu.local_kopere_proctoring_copy",handleContextmenu)}return{init:function(context,cfg){initCopyPolicy(context||{},cfg||{})}}});